def transform(grid):
    """Fill background-colored regions enclosed by the 9/8 boundary with 4."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    wall = 9 if 9 in {v for row in grid for v in row} else 8
    seen = [[False] * w for _ in range(h)]
    q = deque()

    # Mark all non-wall cells connected to the outer edge.
    for r in range(h):
        for c in range(w):
            if (r in (0, h - 1) or c in (0, w - 1)) and grid[r][c] != wall and not seen[r][c]:
                seen[r][c] = True
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= nr < h and 0 <= nc < w and not seen[nr][nc] and grid[nr][nc] != wall:
                seen[nr][nc] = True
                q.append((nr, nc))

    # Enclosed non-wall regions become color 4.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != wall and not seen[r][c]:
                out[r][c] = 4
    return out
